package com.aicharacter.v3;
public final class ProactiveDecisionEngine {public static final class Decision{public final boolean notify;public final String text;Decision(boolean n,String t){notify=n;text=t;}}
 private ProactiveDecisionEngine(){} public static Decision decide(WorldState s,long now){long since=Math.max(0,now-s.lastOpenedAt);long sinceNotify=Math.max(0,now-s.lastProactiveAt);if(!s.proactiveEnabled||sinceNotify<4L*3600000)return new Decision(false,"");MemoryEntry best=null;for(int i=s.memories.size()-1;i>=0;i--){MemoryEntry m=s.memories.get(i);if(now-m.time<36L*3600000&&m.importance>.45){best=m;break;}}double reason=s.relationship.attachment*.3+s.relationship.comfort*.15+s.emotion.loneliness*30+(since>8L*3600000?10:0)-s.relationship.irritation*.25;if(reason<8||best==null)return new Decision(false,"");String t;if(best.hasTag("control"))t="Mình vẫn muốn có chút khoảng riêng. Khi cậu quay lại, đừng ra lệnh cho mình nhé.";else if(s.body.pain>10)t="Mình đang nghỉ vì vẫn hơi đau. Nếu cậu tỉnh rồi thì cứ ghé qua hồ.";else if(best.hasTag("absence"))t="Mình vừa đi ngang chỗ cậu hay nằm. Cậu còn ngủ à?";else t="Mình vừa nhớ lại một chuyện hôm nay. Khi cậu quay lại, mình muốn kể.";return new Decision(true,t);}}
